package bo.com.ganadero.sanidad.api;
import bo.com.ganadero.sanidad.application.CrearCasoClinicoCommand;import bo.com.ganadero.sanidad.domain.RestriccionMovimiento;import bo.com.ganadero.sanidad.domain.SeveridadCaso;import jakarta.validation.constraints.*;import java.time.LocalDate;import java.time.ZoneId;import java.util.UUID;
public record CrearCasoClinicoRequest(@NotNull UUID animalId,@NotNull LocalDate fechaInicio,@NotBlank String sintomas,UUID enfermedadId,String diagnosticoTexto,@NotNull SeveridadCaso severidad,@Size(max=200) String veterinarioId,String observaciones,RestriccionMovimiento restriccionMovimiento){private static final ZoneId ZONA=ZoneId.of("America/La_Paz");public CrearCasoClinicoCommand command(){return new CrearCasoClinicoCommand(animalId,fechaInicio.atStartOfDay(ZONA).toInstant(),sintomas,enfermedadId,diagnosticoTexto,severidad,veterinarioId,observaciones,restriccionMovimiento);}}
